<?php get_header(); ?>
<main id="main" class="page-main"><header class="page-hero site-shell"><p class="eyebrow"><?php esc_html_e('Journal index', 'stillform'); ?></p><h1><?php echo esc_html(is_home() ? __('Journal', 'stillform') : get_the_archive_title()); ?></h1></header><div class="site-shell journal-grid"><?php if (have_posts()) : while (have_posts()) : the_post(); ?><article class="journal-card"><a class="journal-card__image image-reveal" href="<?php the_permalink(); ?>"><?php the_post_thumbnail('stillform-card'); ?></a><p class="eyebrow"><?php echo esc_html(get_the_date('d.m.Y')); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(), 28)); ?></p></article><?php endwhile; else : ?><p><?php esc_html_e('No entries yet.', 'stillform'); ?></p><?php endif; ?></div><div class="site-shell pagination"><?php the_posts_pagination(); ?></div></main>
